package main

import (
	"fmt"
	"sort"
	"strings"
	"unicode/utf8"
)

// maxLine is the repository line limit (GUARDRAILS: 120 characters, Markdown included).
const maxLine = 120

// Doc builds one generated Markdown file. Every line it emits fits maxLine: prose is filled, tables hold short cells,
// and long values go into wrapped list items.
type Doc struct {
	b strings.Builder
}

// NewDoc starts a generated file: the header names the generator and the sources, and says the file is not hand-edited.
func NewDoc(title string, sources ...string) *Doc {
	d := &Doc{}
	d.line("<!-- Generated by `make gen-docs` (cmd/gendocs). Do not edit by hand: " +
		"CI regenerates and fails on a diff. -->")
	d.line("")
	d.line("# " + title)
	d.line("")
	if len(sources) > 0 {
		d.para("Sources: " + strings.Join(sources, "; ") + ".")
	}
	return d
}

func (d *Doc) line(s string) { d.b.WriteString(s + "\n") }

// H2 and H3 write headings.
func (d *Doc) H2(s string) { d.line("## " + s); d.line("") }
func (d *Doc) H3(s string) { d.line("### " + s); d.line("") }

// para writes a paragraph filled to the line limit.
func (d *Doc) para(s string) {
	for _, l := range wrap(s, maxLine, "", "") {
		d.line(l)
	}
	d.line("")
}

// Para writes a paragraph filled to the line limit.
func (d *Doc) Para(format string, a ...any) { d.para(fmt.Sprintf(format, a...)) }

// Bullet writes a list item whose continuation lines are indented.
func (d *Doc) Bullet(s string) {
	for _, l := range wrap(s, maxLine, "- ", "  ") {
		d.line(l)
	}
}

// EndList closes a list with a blank line.
func (d *Doc) EndList() { d.line("") }

// Code writes a fenced block; the caller keeps the lines within the limit.
func (d *Doc) Code(lang string, lines []string) {
	d.line("```" + lang)
	for _, l := range lines {
		d.line(l)
	}
	d.line("```")
	d.line("")
}

// Table writes a table; the cells must be short enough for the row to fit.
func (d *Doc) Table(header []string, rows [][]string) {
	d.line("| " + strings.Join(header, " | ") + " |")
	sep := make([]string, len(header))
	for i := range sep {
		sep[i] = "---"
	}
	d.line("|" + strings.Join(sep, "|") + "|")
	for _, r := range rows {
		d.line("| " + strings.Join(r, " | ") + " |")
	}
	d.line("")
}

// String returns the document.
func (d *Doc) String() string { return strings.TrimRight(d.b.String(), "\n") + "\n" }

// wrap fills s to width, the first line starting with first and the others with rest. A word longer than the room is
// kept whole on its own line (the caller must not produce one).
func wrap(s string, width int, first, rest string) []string {
	var out []string
	cur, n := first, 0
	for _, w := range strings.Fields(s) {
		if n > 0 && utf8.RuneCountInString(cur)+1+utf8.RuneCountInString(w) > width {
			out = append(out, cur)
			cur, n = rest, 0
		}
		if n > 0 {
			cur += " "
		}
		cur += w
		n++
	}
	return append(out, strings.TrimRight(cur, " "))
}

// sortedKeys returns the keys of m in order.
func sortedKeys[V any](m map[string]V) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// firstSentence returns the text up to and including the first sentence end (". " or the end of the text).
func firstSentence(s string) string {
	s = strings.Join(strings.Fields(s), " ")
	for i := 0; i+1 < len(s); i++ {
		if s[i] == '.' && s[i+1] == ' ' {
			return s[:i+1]
		}
	}
	return s
}

// addf appends a formatted problem to the list.
func addf(problems *[]string, format string, a ...any) {
	*problems = append(*problems, fmt.Sprintf(format, a...))
}
